use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_battery_sample(value: *mut Drone_Lifecycle_Governor::Battery_Sample) -> bool;
  fn put_battery_evidence_for_governor(value: *mut Drone_Lifecycle_Governor::Battery_Evidence) -> bool;
  fn put_battery_evidence_for_notice(value: *mut Drone_Lifecycle_Governor::Battery_Evidence) -> bool;
}

pub fn unsafe_get_battery_sample() -> Drone_Lifecycle_Governor::Battery_Sample
{
  unsafe {
    let value: *mut Drone_Lifecycle_Governor::Battery_Sample = &mut Drone_Lifecycle_Governor::Battery_Sample::default();
    get_battery_sample(value);
    return *value;
  }
}

pub fn unsafe_put_battery_evidence_for_governor(value: &Drone_Lifecycle_Governor::Battery_Evidence) -> bool
{
  unsafe {
    return put_battery_evidence_for_governor(value as *const Drone_Lifecycle_Governor::Battery_Evidence as *mut Drone_Lifecycle_Governor::Battery_Evidence);
  }
}

pub fn unsafe_put_battery_evidence_for_notice(value: &Drone_Lifecycle_Governor::Battery_Evidence) -> bool
{
  unsafe {
    return put_battery_evidence_for_notice(value as *const Drone_Lifecycle_Governor::Battery_Evidence as *mut Drone_Lifecycle_Governor::Battery_Evidence);
  }
}

