#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_battery_sample: Mutex<Option<Drone_Lifecycle_Governor::Battery_Sample>> = Mutex::new(None);
  pub static ref OUT_battery_evidence_for_governor: Mutex<Option<Drone_Lifecycle_Governor::Battery_Evidence>> = Mutex::new(None);
  pub static ref OUT_battery_evidence_for_notice: Mutex<Option<Drone_Lifecycle_Governor::Battery_Evidence>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_battery_sample.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_battery_evidence_for_governor.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_battery_evidence_for_notice.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_battery_sample(value: *mut Drone_Lifecycle_Governor::Battery_Sample) -> bool
{
  unsafe {
    let guard = IN_battery_sample.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_battery_evidence_for_governor(value: *mut Drone_Lifecycle_Governor::Battery_Evidence) -> bool
{
  unsafe {
    *OUT_battery_evidence_for_governor.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}

#[cfg(test)]
pub fn put_battery_evidence_for_notice(value: *mut Drone_Lifecycle_Governor::Battery_Evidence) -> bool
{
  unsafe {
    *OUT_battery_evidence_for_notice.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
